//! Activity score: the raw score from the day records and its mapping to 0..100.
//! See `docs/algorithms/metrics.md`; the vectors in the tests are generated by
//! `tools/gen_public_vectors_activity.py`.
//!
//! The score is `round(sum(w_i * c_i) / 100)` over seven contributors in 0..100.
//! The recovery time uses the corrected form and the contributors are athlete-adjusted, with the
//! default distance and vigorous-time references.

/// Combiner weights, in contributor order.
pub const WEIGHTS: [f32; 7] = [25.0, 15.0, 10.0, 10.0, 15.0, 10.0, 15.0];

/// One day record.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Day {
    /// Equivalent walking distance, meters.
    pub eq_distance: u16,
    /// Daily target in the same unit.
    pub eq_target: u16,
    /// Sedentary minutes.
    pub sedentary_min: u16,
    /// Moderate-class MET-minutes.
    pub moderate_met_min: u16,
    /// Vigorous-class MET-minutes.
    pub vigorous_met_min: u16,
    /// Inactivity alerts, read for today only.
    pub sit_alerts: u8,
    /// User age in years, read for today only.
    pub age: u8,
    /// the gender code (1 male, 2 female, 3 other, 0 unknown), today only.
    pub gender: u32,
    /// Moderate-class minutes.
    pub moderate_min: u16,
    /// Vigorous-class minutes.
    pub vigorous_min: u16,
    /// 1 target reached; 0 compare `eq_distance` with `eq_target`; other values not reached.
    pub target_reached: u8,
}

impl Day {
    fn has_data(&self) -> bool {
        self.eq_distance as u32
            + self.sedentary_min as u32
            + self.moderate_met_min as u32
            + self.vigorous_met_min as u32
            + self.moderate_min as u32
            + self.vigorous_min as u32
            != 0
    }

    fn met_target(&self) -> bool {
        self.target_reached == 1 || (self.target_reached == 0 && self.eq_distance >= self.eq_target)
    }
}

const Y: [f32; 4] = [0.0, 25.0, 95.0, 100.0];
/// Reference distance and vigorous time used without a
/// personal override.
const DISTANCE_REF: f32 = 2000.0;
const VIGOROUS_REF: f32 = 160.0;

/// Piecewise-linear interpolation, clamped to the end points; `xs` ascending.
fn interp(x: f32, xs: &[f32], ys: &[f32]) -> f32 {
    if x <= xs[0] {
        return ys[0];
    }
    for i in 1..xs.len() {
        if x <= xs[i] {
            return ys[i - 1] + (ys[i] - ys[i - 1]) * (x - xs[i - 1]) / (xs[i] - xs[i - 1]);
        }
    }
    ys[ys.len() - 1]
}

/// `(moderate, vigorous)` MET category values for an age and sex (linear in
/// `|age - 25|`); zeros for unknown sex.
pub fn met_thresholds(age: u8, gender: u32) -> (f32, f32) {
    // (peak at age 25, decrease per year) for moderate and vigorous.
    const MALE: [(f32, f32); 2] = [(4.832, 0.026), (9.2, 0.0625)];
    const FEMALE: [(f32, f32); 2] = [(5.224, 0.0218), (10.2, 0.05125)];
    let d = (age as f32 - 25.0).abs();
    let at = |c: [(f32, f32); 2]| (c[0].0 - c[0].1 * d, c[1].0 - c[1].1 * d);
    match gender {
        1 => at(MALE),
        2 => at(FEMALE),
        3 => {
            let (m, f) = (at(MALE), at(FEMALE));
            ((m.0 + f.0) / 2.0, (m.1 + f.1) / 2.0)
        }
        _ => (0.0, 0.0),
    }
}

/// The share-of-week rescaling used by contributors 0 and 3: `count / min(n/7, 1)`.
fn weekly(count: f32, n: f32) -> f32 {
    let frac = (n / 7.0).clamp(0.0, 1.0);
    if frac > 0.0 {
        count / frac
    } else {
        count
    }
}

/// Seven raw contributors in 0..100. `days` is oldest to newest and the last item
/// is today; at most nine earlier days are read. `ring_day` is the number of days
/// since the ring was first used (`j`).
pub fn contributors(days: &[Day], ring_day: u32) -> [f32; 7] {
    let Some((today, hist)) = days.split_last() else {
        return [0.0; 7];
    };
    let hist = &hist[hist.len().saturating_sub(9)..];
    let week_hist = &hist[hist.len().saturating_sub(6)..];
    let in_week = || week_hist.iter().chain(std::iter::once(today));

    // c0: meet daily targets
    let (mut met, mut n) = (0.0f32, 0.0f32);
    for d in week_hist.iter().filter(|d| d.has_data()) {
        n += 1.0;
        met += d.met_target() as u8 as f32;
    }
    if today.has_data() {
        if today.met_target() {
            met += 1.0;
            n += 1.0;
        } else if n > 1.0 || met != 0.0 {
            n += 1.0;
        } else {
            // first days of use: an unmet target still counts as met
            met += 1.0;
            n += 2.0;
        }
    }
    let x = weekly(met, n);
    let c0 = if x <= 0.0 {
        0.0
    } else {
        interp(x, &[0.0, 1.0, 5.0, 6.0], &Y).min(100.0)
    };

    // c1, c2
    let c1 = if today.sedentary_min <= 1019 {
        interp(
            today.sedentary_min as f32,
            &[300.0, 400.0, 955.0, 1020.0],
            &[100.0, 95.0, 25.0, 0.0],
        )
    } else {
        0.0
    };
    let c2 = if today.sit_alerts <= 9 {
        interp(
            today.sit_alerts as f32,
            &[0.0, 1.0, 5.0, 10.0],
            &[100.0, 95.0, 25.0, 0.0],
        )
    } else {
        0.0
    };

    // c3: training frequency
    let (mod_val, vig_val) = met_thresholds(today.age, today.gender);
    let (thr_v, thr_m) = ((vig_val - 1.5) * 10.0, (mod_val - 1.5) * 45.0);
    let is_hard_met = |d: &Day| {
        d.vigorous_met_min as f32 > thr_v
            || (d.moderate_met_min as u32 + d.vigorous_met_min as u32) as f32 > thr_m
    };
    let (mut hard, mut n) = (0.0f32, 0.0f32);
    for d in week_hist.iter().filter(|d| d.has_data()) {
        n += 1.0;
        hard += is_hard_met(d) as u8 as f32;
    }
    if today.has_data() {
        if is_hard_met(today) {
            hard += 1.0;
        } else if n <= 1.0 && hard == 0.0 {
            hard += 1.0;
            n += 1.0;
        }
        n += 1.0;
    }
    let x = weekly(hard, n);
    let c3 = if x <= 0.0 {
        0.0
    } else {
        interp(x, &[0.0, 0.5, 2.8, 4.0], &Y).min(100.0)
    };

    // c4: training volume
    const W: [f32; 7] = [0.19, 0.42, 0.77, 1.09, 1.34, 1.53, 1.66];
    let present: Vec<&Day> = in_week().filter(|d| d.has_data()).collect();
    let c4 = if present.is_empty() {
        0.0
    } else {
        let sum: f32 = present
            .iter()
            .enumerate()
            .map(|(k, d)| W[k] * (d.moderate_met_min as u32 + d.vigorous_met_min as u32) as f32)
            .sum();
        interp(
            7.0 / present.len() as f32 * sum,
            &[0.0, 150.0, 850.0, 2000.0],
            &Y,
        )
    };

    // c5, c6: recovery
    let dist_thr = (DISTANCE_REF * 1.01).max(4000.0);
    let vig_thr = (VIGOROUS_REF * 0.75 * 0.125).max(10.0);
    let is_hard = |d: &Day| {
        if ring_day <= 9 {
            d.vigorous_min > 45
        } else {
            dist_thr < d.eq_distance as f32 || vig_thr < d.vigorous_min as f32
        }
    };
    let count = in_week().filter(|d| is_hard(d)).count();
    let c5 = match count {
        0..=5 => 100.0,
        6 => 95.0,
        _ => 0.0,
    };
    let run = hist.iter().rev().take_while(|d| is_hard(d)).count();
    let c6 = if run + 1 >= 2 {
        interp(
            (run + 1) as f32,
            &[2.0, 3.0, 7.0, 9.0],
            &[100.0, 95.0, 25.0, 0.0],
        )
    } else {
        100.0
    };
    [c0, c1, c2, c3, c4, c5, c6]
}

/// Score 0..100 from the day records.
pub fn score(days: &[Day], ring_day: u32) -> u32 {
    let c = contributors(days, ring_day);
    let total: f32 = WEIGHTS.iter().zip(c).map(|(w, v)| w * v).sum::<f32>() / 100.0;
    (total + 0.5) as u32
}

/// Recovery time: `(10 * c5 + 15 * c6) / 25`.
pub fn recovery_time(c: &[f32; 7]) -> f32 {
    (10.0 * c[5] + 15.0 * c[6]) / 25.0
}

#[cfg(test)]
mod tests {
    use super::*;

    macro_rules! vector_tests {
        () => {
    #[test]
    fn matches_reference() {
        for (i, (days, ring_day, want, want_total)) in VECTORS.iter().enumerate() {
            let got = contributors(days, *ring_day);
            for k in 0..7 {
                assert!(
                    (got[k] - want[k]).abs() < 2e-3,
                    "case {i} c{k}: {} vs {}",
                    got[k],
                    want[k]
                );
            }
            let total: f32 = WEIGHTS.iter().zip(got).map(|(w, v)| w * v).sum();
            assert!(
                (total - *want_total as f32).abs() <= 1.0,
                "case {i} total {total} vs {want_total}"
            );
        }
    }
        };
    }

    mod python_port {
        use super::*;
        include!("vectors/activity_score.rs");
        vector_tests!();
    }


    #[test]
    fn empty_input() {
        assert_eq!(contributors(&[], 100), [0.0; 7]);
    }
}
